<section data-butchery-panel="production" <?=$section!=='production'?'hidden':''?> class="form-panel butchery-slaughter-actions"><div class="butchery-slaughter-toolbar"><h3>Fabrication</h3><?php ob_start(); require __DIR__.'/plan_production.php'; ?><?php $butcheryDrawer('Planifier une fabrication',ob_get_clean(),'create','Nouvelle fabrication'); ?></div></section>
<section data-butchery-panel="production" <?=$section!=='production'?'hidden':''?> class="table-panel butchery-history"><header class="butchery-history-heading"><div><h3>Historique des fabrications</h3><p>Tous les ordres · Filtrez par statut et date de production</p></div><span class="butchery-status"><?=count($orders)?> opérations</span></header><?php if(!$orders):?><p class="butchery-empty">Aucune fabrication. Créez un ordre pour commencer.</p><?php endif;?><?php $productionActions=[]; ?><table <?=!$orders?'hidden':''?> class="enterprise-table" data-butchery-history="production"><thead><tr><th>Date</th><th>Ordre / fiche</th><th>Prévu</th><th>Obtenu</th><th>Statut</th><th>Actions</th></tr></thead><tbody><?php foreach($orders as$o): $hasResults=in_array($o['status'],['results_submitted','validated'],true);?><tr data-status="<?=e($o['status'])?>" data-date="<?=e($o['production_date'])?>"><td data-order="<?=e(strtotime($o['production_date']))?>"><?=e(date('d/m/Y',strtotime($o['production_date'])))?></td><td><strong><?=e($o['order_number'])?></strong><small><?=e($o['recipe_name'].' · v'.$o['version_number'])?></small></td><td><?=e(number_format((float)$o['planned_input_kg'],3,',',' '))?> kg</td><td><?=$hasResults?e(number_format((float)$o['output_kg'],3,',',' ')).' kg':'—'?></td><td><span class="butchery-status <?= $o['status']==='validated'?'butchery-status-success':'butchery-status-pending' ?>"><?=e($butcheryStatuses[$o['status']]??$o['status'])?></span></td><td><div class="butchery-production-actions"><?php ob_start(); ?><?php if($o['status']==='in_progress'):?><?php ob_start(); ?><form data-butchery-form data-production-results data-confirm="Soumettre les résultats de cette fabrication ?" method="post" action="<?=e(base_url('butchery/orders/'.$o['id'].'/results'))?>"><?=csrf_field()?><input type="hidden" name="_section" value="<?=e($section)?>"><div class="feed-form-body"><p data-feed-error class="app-alert app-alert-error" role="alert" hidden></p><p class="butchery-plan-recipe"><?=e($o['order_number'].' · '.$o['recipe_name'])?> · Prévu : <?=e($o['planned_input_kg'])?> kg</p><div class="form-grid"><label><span>Lot de matière première *</span><select name="raw_lot_id" required><?php foreach($raw as$x):if($x['status']==='available'):?><option value="<?=$x['id']?>"><?=e($x['lot_number'].' · '.$x['item_name'].' · '.$x['quantity_kg'].' kg · DLC '.$x['expiry_date'])?></option><?php endif;endforeach;?></select></label><label><span>Matière consommée (kg) *</span><input name="raw_quantity_kg" type="number" step="0.001" placeholder="Matière kg" required min="0"></label><details class="butchery-optional"><summary>Additifs (facultatif)</summary><div class="form-grid"><label><span>Additif</span><select name="additive_item_id"><?php foreach($items as$i):if($i['item_kind']==='additive'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select></label><label><span>Additif (kg)</span><input name="additive_quantity_kg" type="number" step="0.001" placeholder="Additif kg" min="0"></label><label><span>Coût unitaire de l’additif</span><input name="additive_unit_cost" type="number" step="0.0001" placeholder="Coût additif" min="0"></label></div></details><label><span>Produit obtenu *</span><select name="finished_item_id" required><?php foreach($items as$i):if($i['item_kind']==='finished_product'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select></label><label><span>Produit obtenu (kg) *</span><input name="output_kg" type="number" step="0.001" placeholder="Produit kg" required min="0"></label><label><span>Coproduit réellement récupéré (facultatif)</span><select name="co_product_item_id"><?php foreach($items as$i):if($i['item_kind']==='co_product'):?><option value="<?=$i['id']?>"><?=e($i['name'])?></option><?php endif;endforeach;?></select></label><label><span>Coproduit (kg)</span><input name="co_product_kg" type="number" step="0.001" placeholder="Coproduit kg" min="0"></label><label><span>Date limite de consommation *</span><input name="expiry_date" type="date" required></label><label><span>DLC du coproduit</span><input name="co_product_expiry_date" type="date"></label><details class="butchery-optional"><summary>Coûts de fabrication (facultatif)</summary><div class="form-grid"><label><span>Coût de main-d’œuvre</span><input name="labor_cost" type="number" step="0.01" placeholder="Main-d’œuvre" min="0"></label><label><span>Coût d’énergie</span><input name="energy_cost" type="number" step="0.01" placeholder="Énergie" min="0"></label><label><span>Frais imputés</span><input name="allocated_cost" type="number" step="0.01" placeholder="Frais imputés" min="0"></label></div></details></div></div><div class="butchery-results-balance" data-results-balance aria-live="polite">Renseignez les quantités pour afficher le bilan.</div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Annuler</button><button type="submit" class="btn-primary">Soumettre résultats</button></footer></form><?php $butcheryDrawer('Saisir les résultats · '.$o['order_number'],ob_get_clean(),'update','Saisir les résultats'); ?><?php elseif($o['status']==='results_submitted'):?><?php ob_start(); ?><form data-butchery-form data-confirm="Confirmer cette opération ?" method="post" action="<?=e(base_url('butchery/orders/'.$o['id'].'/validate'))?>"><?=csrf_field()?><input type="hidden" name="_section" value="<?=e($section)?>"><div class="feed-form-body"><p data-feed-error class="app-alert app-alert-error" role="alert" hidden></p><p class="butchery-empty"><?=e($o['order_number'].' · '.$o['recipe_name'])?><br>Entrée : <?=e($o['actual_input_kg'])?> kg · Produit : <?=e($o['output_kg'])?> kg · Coproduits : <?=e($o['co_product_kg'])?> kg · Pertes : <?=e($o['loss_kg'])?> kg.<br>La validation déduit la matière consommée et crée les lots de produits finis.</p></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Annuler</button><button type="submit" class="btn-primary">Valider la fabrication</button></footer></form><?php $butcheryDrawer('Valider · '.$o['order_number'],ob_get_clean(),'validate','Valider'); ?><?php endif; ?><?php $productionActions[$o['id']]=ob_get_clean(); echo $productionActions[$o['id']]; ?><button type="button" class="btn-secondary" data-workspace-modal-open="production-detail-<?=e($o['id'])?>" aria-label="<?=e('Consulter '.$o['order_number'])?>">Consulter</button></div></td></tr><?php if($section==='production'){ob_start();require __DIR__.'/production_detail.php';$butcheryModals[]=ob_get_clean();} endforeach;?></tbody></table></section>
